-- Initial schema for todo. All rows belong to one user and are protected by row level security.
-- Ids are generated by the client (crypto.randomUUID), so no default is needed.

create table public.task_lists (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  color text not null default '#7f9a72' check (color ~ '^#[0-9a-fA-F]{6}$'),
  position integer not null default 0,
  created_at timestamptz not null default now()
);

create table public.tasks (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  list_id uuid references public.task_lists (id) on delete set null,
  title text not null check (char_length(title) between 1 and 300),
  description text not null default '' check (char_length(description) <= 5000),
  due_date date,
  priority smallint not null default 0 check (priority between 0 and 3),
  completed_at timestamptz,
  position integer not null default 0,
  created_at timestamptz not null default now()
);

create table public.habits (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  icon text not null check (icon in ('dumbbell', 'book-open', 'graduation-cap', 'heart', 'leaf', 'sun')),
  color text not null check (color in ('rose', 'blue', 'sage', 'lavender', 'amber', 'peach')),
  kind text not null check (kind in ('yesNo', 'duration', 'quantity')),
  unit text not null default '' check (char_length(unit) <= 20),
  target double precision check (target is null or target > 0),
  goal_period text not null default 'daily' check (goal_period in ('daily', 'weekly')),
  position integer not null default 0
);

create table public.habit_entries (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  habit_id uuid not null references public.habits (id) on delete cascade,
  entry_date date not null,
  value double precision not null check (value >= 0),
  unique (habit_id, entry_date)
);

create index tasks_user_position_idx on public.tasks (user_id, position);
create index task_lists_user_position_idx on public.task_lists (user_id, position);
create index habits_user_position_idx on public.habits (user_id, position);
create index habit_entries_user_date_idx on public.habit_entries (user_id, entry_date);

alter table public.task_lists enable row level security;
alter table public.tasks enable row level security;
alter table public.habits enable row level security;
alter table public.habit_entries enable row level security;

create policy "Users manage their own task lists" on public.task_lists
  for all to authenticated
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create policy "Users manage their own tasks" on public.tasks
  for all to authenticated
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create policy "Users manage their own habits" on public.habits
  for all to authenticated
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create policy "Users manage their own habit entries" on public.habit_entries
  for all to authenticated
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- Anonymous visitors get no access at all.
revoke all on public.task_lists, public.tasks, public.habits, public.habit_entries from anon;
